// Twelve-hourly consent watch (spec 005 section 4.2.1). Mints one JWT per stored
// account for GET /accounts/{uid}/balances. That is a real data fetch, which is
// what makes Enable Banking renew the ASPSP token internally (FAQ: "token
// renewal is handled automatically during data fetch requests whenever
// required"), and it is also the authoritative liveness signal. 12h, not 6h:
// the fleet was spending ~8 ASPSP data fetches a day per account against a
// ~4/day background limit, and consent drops have happened since the
// integration started whatever the cadence - so the watch buys detection, not
// prevention, at the cadence the budget allows. Only external modules and web
// globals are used.
const jwt = require('jsonwebtoken');

const stable = $('Get Stable Secret').first().json;
const accounts = JSON.parse(atob(stable.data['accounts.json']));
const pem = atob(stable.data['private_key']);

const tokenGet = $('Get Token Secret').first().json;
let tokensByAlias = {};
if (tokenGet.statusCode === 200) {
  const raw = (tokenGet.body.data || {})['tokens.json'];
  tokensByAlias = raw ? JSON.parse(atob(raw)) : {};
}

const probes = [];
for (const [alias, cfg] of Object.entries(accounts)) {
  const entry = tokensByAlias[alias];
  if (!entry || !entry.uid) {
    continue;
  }
  probes.push({
    alias,
    uid: entry.uid,
    jwt: jwt.sign(
      { iss: 'enablebanking.com', aud: 'api.enablebanking.com' },
      pem,
      { algorithm: 'RS256', keyid: cfg.app_id, expiresIn: 3600 }
    ),
  });
}
if (Object.keys(accounts).length > 0 && probes.length === 0) {
  // Configured accounts with no probeable session mean the token Secret is
  // missing or empty: the watch would probe nothing, report "unchanged" and
  // stay silent forever. Fail so the error workflow says so - the daily
  // check's Mint Session JWT throws in the same case.
  throw new Error('no session uid to probe: finance-enablebanking-token is missing or empty');
}
return probes.map((probe) => ({ json: probe }));

// Report when a stored account's data-plane state differs from the previous
// run's, persisted in workflow static data so an unchanged run posts nothing.
// The state comes from GET /accounts/{uid}/balances, so a dead consent reads
// EXPIRED_SESSION here even while GET /sessions/{id} still says AUTHORIZED. A
// rate limit is recorded but never posted - it is not a consent problem. A
// non-OK state seen for the first time (fresh static data, a new alias, or a
// consent already dead when the watch was deployed) is posted too: consent
// drops have happened since the integration started, and a transitions-only
// rule would silence the very first observation of one forever.
const probes = $('Build Probes').all().map((item) => item.json);
const responses = $input.all().map((item) => item.json);
const staticData = $getWorkflowStaticData('global');
const previous = staticData.consent_states || {};

const next = {};
const changes = [];
probes.forEach((probe, index) => {
  const resp = responses[index] || {};
  const body = resp.body || {};
  const errorName = body.error || body.code || '';
  const rateLimited =
    resp.statusCode === 429 || errorName === 'ASPSP_RATE_LIMIT_EXCEEDED';
  const state = resp.statusCode === 200 ? 'OK' : errorName || `HTTP ${resp.statusCode}`;
  const seen = previous[probe.alias] !== undefined;
  next[probe.alias] = state;
  if (rateLimited) {
    return;
  }
  if (seen && previous[probe.alias] !== state) {
    changes.push(`- *${probe.alias}*: ${previous[probe.alias]} -> ${state}`);
  } else if (!seen && state !== 'OK') {
    changes.push(`- *${probe.alias}*: first observation, already ${state}`);
  }
});
staticData.consent_states = next;

const changed = changes.length > 0;
return [
  {
    json: {
      changed,
      text: changed
        ? `Enable Banking consent state changed:\n${changes.join('\n')}\n\nRenew if it is not OK (the bank login is the one manual step): https://automation-n8n.homelab.alvsanand.com/form/0c19a176-7e58-419a-9a26-b5d1ca2f578f`
        : 'consent state unchanged',
    },
  },
];

